function isPalindrome(text) {
  const cleaned = text.toLowerCase().split(' ').join('');
  const backwards = cleaned.split('').reverse().join('');
  return cleaned === backwards;
}

Cleaning first removes case and spaces, then a string equals its reverse exactly when it is a palindrome.
